INSERT INTO public.urls (id, short_id, url, title, description, og_image_url, skill_count, tag_suggestions, created_at, updated_at) VALUES ('10000000-0000-0000-0000-000000000077', 'jzBrM5N1', 'https://ruben.substack.com/p/claude-skills', 'Claude Skills (the non-developer guide) — Ruben Hassid', null, null, null, null, now(), now());
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'the skill that writes other skills. weirdly recursive but the structure here is the cleanest example i''ve seen of how a SKILL.md should actually feel — opinionated description, "pushy" trigger language, a real test loop. starting point for everything i''m writing now.', '{"skill-authoring","meta","agentic-design"}', '2026-03-12T09:14:00Z', '2026-03-12T09:14:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'the piece that made the penny drop for me on why this isn''t just AGENTS.md with extra steps. the bit about skills outsourcing to the harness instead of being the protocol is doing a lot of work.', '{"agentic-design","mcp","field-notes"}', '2026-03-15T14:22:00Z', '2026-03-15T14:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000003', 'jesse''s whole superpowers stack. brainstorm → plan → execute as enforced skills, not just vibes. been pulling individual ones out (brainstorming, writing-plans) rather than installing the whole thing — too much methodology for how i work.', '{"claude-code","tdd","methodology"}', '2026-03-18T11:42:00Z', '2026-03-18T11:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000004', '45 rules across 8 categories, prioritised by impact. interesting as a *shape* — most skills are how-to, this is more like a linter that explains itself. design pattern worth borrowing.', '{"frontend","performance","next-js"}', '2026-03-20T16:05:00Z', '2026-03-20T16:05:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000005', 'the "would removing this cause Claude to make mistakes? if not, cut it" line for CLAUDE.md is the test i''ve been missing. half my project files are bloated for no reason.', '{"claude-code","claude-md","field-notes"}', '2026-03-22T10:18:00Z', '2026-03-22T10:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000006', 'the canonical reference. mostly using it as a sanity check on my own skill structures — if mine drift too far from the docx and pdf shapes, something is probably off.', '{"agent-skills","reference"}', '2026-03-25T08:50:00Z', '2026-03-25T08:50:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000007', 'the essay behind the framework. reads more honestly than the repo readme — the bit about TDD-for-agents being more useful than TDD-for-humans is doing a lot of work in my head right now.', '{"methodology","field-notes"}', '2026-03-28T19:33:00Z', '2026-03-28T19:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000008', 'anthropic shipped evals into skill-creator. the framing of "capability uplift" vs "encoded preference" skills is the categorisation i''ve been missing — explains why some of mine should be tighter and others should just be richer.', '{"skill-authoring","evals"}', '2026-04-02T11:15:00Z', '2026-04-02T11:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000009', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000009', 'reading this for the third time. the trigger conditions are surgical in a way most of mine aren''t — the SKIP clauses at the bottom do as much work as the triggers themselves.', '{"skill-craft","production-skills"}', '2026-04-05T13:07:00Z', '2026-04-05T13:07:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000010', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000010', 'useful as a paired read with docx. the form-filling section is the part that earned its place — most pdf skills assume forms are someone else''s problem.', '{"skill-craft","production-skills"}', '2026-04-05T13:15:00Z', '2026-04-05T13:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000011', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000011', 'the contrarian counterweight to all the hype. the claim that 80% of public skills hurt output is uncomfortable to read but probably right. the framing of skills as "prompt injections" deflates a lot of the marketing language.', '{"evals","field-notes"}', '2026-04-08T09:22:00Z', '2026-04-08T09:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000012', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000012', 'the postgres-best-practices skill is the one i actually use. the rest of the repo is interesting as a *pattern* — vendor-shipped skills as the new docs surface.', '{"agent-skills","postgres"}', '2026-04-10T15:48:00Z', '2026-04-10T15:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000013', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000013', 'the most navigable of the awesome-lists. been using it more as a discovery surface than a curation. some entries are clearly there for completeness rather than quality.', '{"awesome-list","landscape"}', '2026-04-12T08:12:00Z', '2026-04-12T08:12:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000014', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000014', 'the reference doc inside the skill-creator. the section on red flags ("if your skill description doesn''t make claude *want* to use it...") is the bit i keep reading.', '{"skill-authoring","field-notes"}', '2026-04-13T17:05:00Z', '2026-04-13T17:05:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000015', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000015', 'the one superpowers skill i actually kept. forces a multi-angle pass before claude commits to a direction — useful for design exploration where i''d otherwise get a too-eager first answer.', '{"claude-code","design-process"}', '2026-04-15T11:33:00Z', '2026-04-15T11:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000016', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000016', 'the design tool itself i''m still working out my view on. the "build a design system from your codebase" promise is the load-bearing claim — the demo looks impressive but the real test is what happens when you try to evolve it later.', '{"design-tools","field-notes"}', '2026-04-17T09:48:00Z', '2026-04-17T09:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000017', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000017', 'vendors shipping their own skills directly. this is the pattern i think wins long-term — way better than community guesses at "how do i use terraform".', '{"agent-skills","agentic-design"}', '2026-04-19T14:10:00Z', '2026-04-19T14:10:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000018', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000018', 'the four-element prompt structure for skill-creator is the takeaway. been using it as a checklist when i scaffold a new skill — something i was previously eyeballing.', '{"skill-authoring","field-notes"}', '2026-04-21T10:25:00Z', '2026-04-21T10:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000019', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000019', 'the bit about "you''re really testing the coding agent''s problem solving, not your skill" is a useful reframe. been guilty of writing test cases that the base model would pass anyway.', '{"evals","agentic-design"}', '2026-04-22T13:55:00Z', '2026-04-22T13:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000020', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000020', 'third in the docx/pdf/pptx trio. the file-format-as-skill pattern across all three is what i''m actually studying — they share more structure than the surface contents suggest.', '{"skill-craft","production-skills"}', '2026-04-23T08:40:00Z', '2026-04-23T08:40:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000021', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000021', 'weird name, useful collection. the cloud-cli skills (supabase, vercel, fly.io) are the part i kept. the agent-flywheel framing itself i''m not sure i buy.', '{"agent-skills","dev-tools"}', '2026-04-24T16:18:00Z', '2026-04-24T16:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000022', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000022', 'the three-stage workflow (Context → Refinement → Reader Testing) is honestly how i want to work on design specs too. been borrowing the "test the doc with a fresh claude with no context" move.', '{"writing-process","skill-craft"}', '2026-04-25T11:02:00Z', '2026-04-25T11:02:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000023', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000023', 'the announcement post for their skills repo. mainly saved for the "why we built this" framing — the gap between "agent knows the tool" and "agent uses the tool correctly" is the real one.', '{"agentic-design","field-notes"}', '2026-04-26T09:30:00Z', '2026-04-26T09:30:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000024', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000024', 'the design-system-builder pattern (extract brand from URL, generate a reusable skill) is the part worth saving. less interested in the specific implementation, more in the *meta-skill* idea — skills that build other skills.', '{"design-tools","skill-authoring"}', '2026-04-27T14:48:00Z', '2026-04-27T14:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000025', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000025', 'the TDD-for-documentation framing is the right mental model. watch the agent fail without the skill, write the skill, watch it pass. used this approach for the last three skills i wrote.', '{"skill-craft","tdd-for-skills"}', '2026-04-28T10:12:00Z', '2026-04-28T10:12:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000026', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000004', 'This is the new baseline for any React/Next perf review. The prefix codes (async-parallel, bundle-barrel-imports) are the most underrated part — they make rules linkable in code review the way ESLint rule names became. Copy this pattern when you write your own team rules skill.', '{"react-performance","next-js","design-engineering","frontend"}', '2025-12-08T10:14:00Z', '2025-12-08T10:14:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000027', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000009', 'Useful less for what it does and more for *how it''s written*. The trigger conditions are surgical — "Trigger whenever the user mentions ''deck,'' ''slides,'' ''presentation,'' or references a .pptx filename" — and the SKIP clauses do as much work as the triggers. Use when modelling a skill that could be over-claimed.', '{"document-generation","skill-craft","production-skills"}', '2025-12-12T16:42:00Z', '2025-12-12T16:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000028', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000026', 'The whole shelf — react-best-practices is the famous one, but the web-best-practices and react-composition skills are quietly excellent. Worth saving the root not just the leaf.', '{"agent-skills","vercel","design-engineering"}', '2025-12-15T09:28:00Z', '2025-12-15T09:28:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000029', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000006', 'The canonical reference. Read /docx and /pdf as exemplars of mature skills — they do the unglamorous work of error handling and validation that most community skills skip. Use when calibrating your own skill quality.', '{"agent-skills","reference","production-skills"}', '2025-12-20T11:55:00Z', '2025-12-20T11:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000030', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000025', 'The TDD-for-documentation framing is the right mental model. Watch the agent fail without the skill, write the skill, watch it pass. Use when you''re tempted to write a skill from scratch without first establishing the baseline behaviour you''re trying to change.', '{"skill-craft","tdd-for-skills","meta"}', '2026-01-04T14:22:00Z', '2026-01-04T14:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000031', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000027', 'Mirrors the Vercel react-best-practices structure — impact-prioritised, prefix-coded, linkable in code review. Use when building team-shared infra skills; this is the shape that scales.', '{"postgres","supabase","design-engineering","production-skills"}', '2026-01-09T09:48:00Z', '2026-01-09T09:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000032', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000010', 'Companion to /docx. The form-filling section is where most community PDF skills give up — Anthropic''s version handles edge cases (non-fillable forms, coordinate-based positioning) properly. Use when designing skills that must handle partial-input cases gracefully.', '{"document-generation","skill-craft","production-skills"}', '2026-01-14T11:33:00Z', '2026-01-14T11:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000033', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000028', 'The async/await section is the clearest explanation of the suspense boundary mental model I''ve found. Use when onboarding someone to RSC who already knows hooks but is fuzzy on the data-loading lifecycle.', '{"react-server-components","reference","frontend"}', '2026-01-18T16:08:00Z', '2026-01-18T16:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000034', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000029', 'The blog post that anchors the skill. The "performance work fails because it starts too low in the stack" framing is the quote I keep coming back to in code reviews. Use when explaining to a team why a perf audit needs to start at the data-fetching layer.', '{"react-performance","essay","frontend"}', '2026-01-22T10:15:00Z', '2026-01-22T10:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000035', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000001', 'The meta-skill that scaffolds new ones. The frontmatter conventions and the "pushy description" guidance are the load-bearing parts — skip these and your skills won''t fire reliably. Use when training someone to write their first skill.', '{"skill-authoring","meta","production-skills"}', '2026-01-26T13:42:00Z', '2026-01-26T13:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000036', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000030', 'The decision tree for "when to use a server component vs a client component" is the section I keep linking the team to. Use when onboarding a Next 15+ project and someone defaults to ''use client'' on every file.', '{"react-server-components","next-js","reference"}', '2026-02-01T09:55:00Z', '2026-02-01T09:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000037', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000031', 'The mental model that explains why server components feel different from client components without resorting to plumbing. Use when someone is confused about why this is a paradigm shift, not just a runtime change.', '{"react-server-components","essay","mental-model"}', '2026-02-05T14:18:00Z', '2026-02-05T14:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000038', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000020', 'Third in the docx/pdf/pptx trio. Worth reading all three together — the shared structure (trigger conditions, file locations, source-type detection) is the actual lesson, not any individual skill''s contents. Use when designing a family of related skills.', '{"document-generation","skill-craft","production-skills"}', '2026-02-09T11:25:00Z', '2026-02-09T11:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000039', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000016', 'The brand-from-codebase claim is the interesting one. Whether it actually preserves design-system fidelity in practice is the open question — extraction is easy, evolution is hard. Use as a reference when discussing design-tool generation with a team.', '{"design-tools","design-systems","field-notes"}', '2026-02-14T15:48:00Z', '2026-02-14T15:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000040', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000008', 'The eval framework finally landing in skill-creator. The "capability uplift vs encoded preference" distinction is a useful taxonomy — explains why some skills should expire as models improve and others shouldn''t. Use when categorising team skill investments.', '{"skill-authoring","evals","production-skills"}', '2026-02-18T10:12:00Z', '2026-02-18T10:12:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000041', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000022', 'The three-stage workflow (Context → Refinement → Reader Testing) translates cleanly to design specs. The "test the doc with a fresh Claude" move is now in my standard handoff process — catches assumptions you didn''t know you were making.', '{"writing-process","skill-craft","design-engineering"}', '2026-02-22T13:33:00Z', '2026-02-22T13:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000042', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000012', 'Same vendor-shipping-skills pattern as Vercel''s. The supabase-postgres-best-practices skill is the standout, but the supabase-cli skill is what the team actually uses day-to-day. Use the root for landscape view, individual skills for installation.', '{"agent-skills","supabase","design-engineering"}', '2026-02-26T09:20:00Z', '2026-02-26T09:20:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000043', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000014', 'The reference doc inside skill-creator. The "red flags" section ("if your description doesn''t make Claude *want* to use it") is the single most-quoted bit when I''m reviewing skills the team has written. Use when running skill-craft sessions.', '{"skill-authoring","reference","production-skills"}', '2026-03-02T11:05:00Z', '2026-03-02T11:05:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000044', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000019', 'The sharpest write-up on skill evaluation I''ve found. The point about "don''t make tasks too adversarial — you''ll end up testing the agent, not your skill" is non-obvious and important. Use when designing eval suites for team skills.', '{"evals","skill-authoring","production-skills"}', '2026-03-06T15:42:00Z', '2026-03-06T15:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000045', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000032', 'The quieter sibling to react-best-practices. Covers HTML semantics, performance budgets, accessibility — the things that get cut from React-specific guides. Use when reviewing landing pages or marketing sites where React is overkill.', '{"frontend","accessibility","web-platform"}', '2026-03-10T10:33:00Z', '2026-03-10T10:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000046', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000033', 'The composition-over-configuration argument applied to component design. Less famous than react-best-practices but probably more useful for design-system work. Use when reviewing components that have grown too many props.', '{"frontend","design-systems","component-api"}', '2026-03-13T14:18:00Z', '2026-03-13T14:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000047', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000011', 'The eval-first framing is the right approach. Disagree with the conclusion that 80% of public skills hurt — that number depends heavily on what you''re benchmarking against — but the methodology of measuring trigger rate and output quality is sound. Use when you need a counter-balance to the skills hype.', '{"evals","skill-authoring","field-notes"}', '2026-03-17T09:55:00Z', '2026-03-17T09:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000048', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000034', 'INP replaced FID as a Core Web Vital and most teams haven''t updated their measurement strategy. This is the canonical reference. Use when reviewing performance budgets that reference older Core Web Vitals.', '{"frontend","performance","web-platform"}', '2026-03-21T11:42:00Z', '2026-03-21T11:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000049', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000015', 'The single most useful superpowers skill for design work. Forces a multi-angle pass before committing — counters Claude''s bias toward the first plausible answer. Use when exploring component patterns before locking on one.', '{"design-process","claude-code","skill-craft"}', '2026-03-25T16:08:00Z', '2026-03-25T16:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000050', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000035', 'Cascade layers solve the specificity problem that has plagued every design system I''ve worked on. The migration story is the part worth reading carefully — it''s mostly painless, but the gotchas around third-party CSS are real. Use when scoping a design-system refactor.', '{"css","design-systems","design-engineering"}', '2026-04-01T10:25:00Z', '2026-04-01T10:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000051', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000036', 'Decision tree at the top is the right shape for "which surface do I use" skills. The Bedrock/Vertex carve-out at step 0 is the kind of guardrail you only write after watching agents pick the wrong path three times.', '{"claude-api","tool-use","managed-agents"}', '2025-12-05T08:42:00Z', '2025-12-05T08:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000052', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000003', 'The interesting move here isn''t the individual skills, it''s the SessionStart hook that forces skill discovery before the first response. Composability through forced search beats composability through naming conventions every time.', '{"claude-code","tdd","agent-methodology"}', '2025-12-09T11:18:00Z', '2025-12-09T11:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000053', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000002', 'The MCP-vs-skills framing here is correct but undersells the practical difference: MCP is a protocol you have to design *to*, skills are markdown you have to design *with*. Different cognitive load, different failure modes.', '{"mcp","agent-architecture","protocol-design"}', '2025-12-13T15:55:00Z', '2025-12-13T15:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000054', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000006', 'Canonical. Read /skill-creator first. The "make descriptions pushy" guidance is non-obvious and I keep seeing skills fail discovery for not following it.', '{"agent-skills","reference"}', '2025-12-17T09:30:00Z', '2025-12-17T09:30:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000055', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000011', '"I installed all 47. Tested every single one. Forty made the output worse." Worth reading even if you disagree (I half-disagree). Real eval discipline applied to the skills hype cycle. The trigger-rate measurement specifically is the missing primitive.', '{"eval-design","wip-skill-quality","field-notes"}', '2025-12-22T13:48:00Z', '2025-12-22T13:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000056', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000037', 'The reference essay. The augmented-LLM-vs-agent distinction at the top is the framework everyone working on agents should converge on. The orchestrator-workers pattern is the only one I use in production.', '{"agent-architecture","agentic-design","reference"}', '2025-12-28T10:22:00Z', '2025-12-28T10:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000057', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000007', 'The remembering-conversations skill described at the end is a quietly important pattern: SQLite + vector index + Haiku summary as long-term memory. Cheap, durable, model-agnostic. The whole essay is good, but that section is the load-bearing one.', '{"agent-architecture","memory","wip-patterns"}', '2026-01-03T16:15:00Z', '2026-01-03T16:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000058', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000019', 'Half-right. The point about "you''re testing the coding agent, not the skill" is correct. The Docker-scaffold-for-reproducibility recommendation is overkill for most teams — adds friction without improving signal at the early stages.', '{"eval-design","agentic-design"}', '2026-01-08T11:42:00Z', '2026-01-08T11:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000059', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000001', 'The meta-skill. Read the YAML frontmatter rules carefully — the description field is what makes or breaks discovery, and most community skills get this wrong. Non-obvious primitive.', '{"skill-authoring","meta","agent-architecture"}', '2026-01-12T14:08:00Z', '2026-01-12T14:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000060', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000038', 'The methodology section is more useful than the headline number. The way they structure the agent loop — file edit, run tests, observe, retry — is the same shape that works for production agents. Eval-rig design is half the work.', '{"evals","agent-architecture","swe-bench"}', '2026-01-17T09:50:00Z', '2026-01-17T09:50:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000061', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000008', 'Eval framework finally landed. The capability-uplift vs encoded-preference distinction is the right taxonomy — capability-uplift skills should expire, encoded-preference skills shouldn''t. Useful for thinking about which skills are worth maintaining.', '{"evals","skill-authoring","agent-architecture"}', '2026-01-22T13:25:00Z', '2026-01-22T13:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000062', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000017', 'Vendor-shipped skills. The terraform-style-guide skill is the model — codified opinions, not just docs. This pattern (vendors ship skills with their tools) is the long-term structural answer to LLM hallucination on infrastructure code.', '{"agent-skills","vendor-skills","infrastructure"}', '2026-01-26T11:18:00Z', '2026-01-26T11:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000063', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000027', 'The impact-prioritised skill format with CRITICAL/HIGH/MEDIUM-HIGH/MEDIUM/LOW tiers is the right structure for opinionated docs. Each rule has a quantified benefit ("10-100x faster"). Use when designing skills with non-obvious priority hierarchies.', '{"postgres","skill-craft","agent-architecture"}', '2026-01-30T15:42:00Z', '2026-01-30T15:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000064', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000039', 'The lead-agent-spawns-subagents pattern is now the default for any complex research task. Token cost is real but worth it for the parallelism. The retry-and-self-critique loop at the end is the part most implementations skip.', '{"multi-agent","agent-architecture","research"}', '2026-02-04T10:08:00Z', '2026-02-04T10:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000065', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000040', 'Anton''s terraform skill — the alternative to HashiCorp''s official one. ~4400 token activation cost is high. The decision matrices are the differentiator vs vendor-shipped versions. Use when team needs deeper testing-strategy guidance than the official skills provide.', '{"agent-skills","infrastructure","wip-evaluating"}', '2026-02-08T14:33:00Z', '2026-02-08T14:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000066', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000041', 'The interesting counter to terraform-skill. ~600 token activation cost (7x leaner). Forces a diagnostic sequence before generating code. Whether the diagnostic-first approach beats the reference-first approach is genuinely open — depends on your failure modes.', '{"agent-skills","infrastructure","agent-architecture"}', '2026-02-12T11:55:00Z', '2026-02-12T11:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000067', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000042', 'Interpretability research, but useful operationally — the circuit-level understanding of how models route through prompts changes how you write skill descriptions. The bit on attention heads selecting between competing instructions is the practical takeaway.', '{"interpretability","agent-architecture","field-notes"}', '2026-02-17T09:20:00Z', '2026-02-17T09:20:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000068', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000004', 'Saving the React skill from an agent-architecture angle, not a frontend angle. The prefix-codes-as-rule-IDs pattern is the right way to make skill rules linkable across context. Borrowing it for our internal eval-design skill.', '{"skill-craft","agent-architecture","rule-design"}', '2026-02-21T13:42:00Z', '2026-02-21T13:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000069', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000014', 'The reference doc inside skill-creator. The "red flags" section is the most quoted thing in skill-craft discussions for a reason. "If your description doesn''t make Claude *want* to use it" is a useful diagnostic.', '{"skill-authoring","reference"}', '2026-02-26T10:15:00Z', '2026-02-26T10:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000070', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000043', 'The TDD-for-plans framing — write the test for the plan before the plan itself. Most planning skills get this backwards. The forced explicit-success-criteria step is the load-bearing constraint.', '{"claude-code","skill-craft","planning"}', '2026-03-02T15:08:00Z', '2026-03-02T15:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000071', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000044', 'Context-augmented chunking before embedding. ~35% improvement on retrieval failures in their benchmarks. Cheap to implement (one Haiku call per chunk). The non-obvious primitive most RAG systems are missing.', '{"rag","retrieval","agent-architecture"}', '2026-03-07T11:32:00Z', '2026-03-07T11:32:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000072', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000012', 'Supabase shipping their own skills. Same pattern as Vercel and HashiCorp. Vendor-shipped skills are the structural answer to LLM hallucination on tool-specific code — community skills can''t keep up with version churn.', '{"agent-skills","vendor-skills","agent-architecture"}', '2026-03-11T14:48:00Z', '2026-03-11T14:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000073', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000045', 'Reference for cross-model thinking. The structural differences between OpenAI''s tool-calling, Anthropic''s tool-use, and skills-as-injected-instructions are worth holding side by side — they''re not interchangeable, and the failure modes are different.', '{"tool-use","openai","agent-architecture"}', '2026-03-15T09:55:00Z', '2026-03-15T09:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000074', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000007', 'Re-reading after six months. The TDD-for-agents argument has aged well — the bit about test-first being more important for agents than humans (because the agent has no shame) is the load-bearing observation.', '{"agent-architecture","tdd","field-notes"}', '2026-03-19T13:20:00Z', '2026-03-19T13:20:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000075', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000046', 'Haiku 4.5 is the right model for sub-agent work — small enough to run cheaply in parallel, capable enough to handle the orchestrator-workers pattern. The eval numbers on agentic coding are the relevant ones, not the headline benchmarks.', '{"models","agent-architecture","haiku"}', '2026-03-23T10:42:00Z', '2026-03-23T10:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000076', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000005', 'Cut my CLAUDE.md from 800 lines to 180 after reading this and Claude actually started following the rules. 🚢 The "would removing this cause Claude to make mistakes" test is harsh and correct.', '{"claude-code","ship-this-week","dev-velocity"}', '2026-01-15T09:22:00Z', '2026-01-15T09:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000077', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000047', 'The status line config alone saved me an hour a week of "wait what model am I on." Stole 4 of these for my workflow on day one.', '{"claude-code","dev-velocity","tips"}', '2026-01-18T14:48:00Z', '2026-01-18T14:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000078', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000001', 'Used this to write a "landing-page-copy" skill that now writes my product page hero copy in my voice. Took 20 minutes. The pushy-description guidance is the only reason it actually fires when I need it.', '{"skill-authoring","ship-this-week"}', '2026-01-22T11:15:00Z', '2026-01-22T11:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000079', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000029', '600ms off my checkout page after applying maybe 6 of the 40 rules. 🚢 The waterfall stuff is where most of my wins were — I was awaiting things in series for no reason.', '{"react","next-js","cut-cost"}', '2026-01-25T16:32:00Z', '2026-01-25T16:32:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000080', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000003', 'Tried this for two weeks on my last build. The brainstorm → plan → execute loop is good, but the TDD enforcement slowed me down for a project that didn''t need it. Going to install just the brainstorming skill on its own next time.', '{"claude-code","methodology","wip-evaluating"}', '2026-01-29T10:08:00Z', '2026-01-29T10:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000081', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000048', 'Useful as a sanity check on velocity expectations. Most of the "30 days" framing is misleading — they were small products, but the workflow itself (skill per product type, shared CLAUDE.md template) is the part worth stealing.', '{"dev-velocity","indie-hacking","field-notes"}', '2026-02-02T13:42:00Z', '2026-02-02T13:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000082', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000011', 'Made me audit my own skills folder. Killed 3 of 8 skills I wasn''t actually using. Faster output immediately. 🚢 The trigger-rate measurement is the bit I''d been doing by gut.', '{"claude-code","cut-cost","field-notes"}', '2026-02-06T15:18:00Z', '2026-02-06T15:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000083', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000049', 'Shipped paid plans in a weekend using this. 🚢 The "hosted by Stripe" option means I never touch a card field. Saves me legal-compliance pages of work.', '{"stripe","monetisation","ship-this-week"}', '2026-02-10T09:55:00Z', '2026-02-10T09:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000084', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000012', 'Installed the supabase + postgres-best-practices skills last week. Claude stopped writing migrations that violated my RLS policies. 🚢 Saved me a security incident.', '{"supabase","ship-this-week","cut-cost"}', '2026-02-14T11:25:00Z', '2026-02-14T11:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000085', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000050', 'Useful as a stripped-down stack reference. The point about not adding dependencies until you have revenue is one I keep forgetting. Going back to it next time I''m tempted to add Posthog before I have users.', '{"indie-hacking","monetisation","field-notes"}', '2026-02-18T14:08:00Z', '2026-02-18T14:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000086', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000051', 'Shipped Posthog on my main product after reading this. 🚢 Three events that matter (signup, paywall hit, payment), nothing else. Way more useful than what I was tracking before.', '{"analytics","ship-this-week","indie-hacking"}', '2026-02-22T10:42:00Z', '2026-02-22T10:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000087', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000006', 'Skipped most of these (too generic for what I do) but the docx and pptx skills got me out of a client-deliverable hole last month. 🚢 Worth the install just for those two.', '{"agent-skills","ship-this-week"}', '2026-02-26T13:15:00Z', '2026-02-26T13:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000088', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000016', 'Used this for my new landing page in 90 minutes. 🚢 Would have taken 3 days with my previous workflow. The auto-applied design system is the load-bearing feature for me — I don''t want to rebuild brand fidelity every time.', '{"design-tools","landing-pages","ship-this-week"}', '2026-03-02T11:33:00Z', '2026-03-02T11:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000089', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000024', 'Followed this end-to-end. Now my LinkedIn carousels and landing pages all match my product brand without me thinking about it. 🚢 The "meta-skill that builds your brand skill" pattern is genuinely useful.', '{"design-tools","ship-this-week","landing-pages"}', '2026-03-06T09:48:00Z', '2026-03-06T09:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000090', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000052', 'The Image component config that finally fixed my LCP. Took my main landing from 4.2s to 1.8s. 🚢 cut-cost on Vercel bandwidth bill too because the optimised images are smaller.', '{"next-js","cut-cost","ship-this-week"}', '2026-03-10T15:22:00Z', '2026-03-10T15:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000091', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000053', 'The argument is: build the thing in 2 days using Claude Code instead of scoping for 2 weeks. I half-buy this — works for landing pages, doesn''t work for anything with real state. Useful counter-take to read against my own habits.', '{"dev-velocity","indie-hacking","field-notes"}', '2026-03-14T11:08:00Z', '2026-03-14T11:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000092', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000054', 'Migrated my whole setup in 20 minutes following this. 🚢 Then went back to Claude Code two weeks later because the agent loop was tighter for my use case. Useful to have read it though — knowing what Cursor does differently helped me appreciate what I had.', '{"cursor","dev-velocity","field-notes"}', '2026-03-18T14:42:00Z', '2026-03-18T14:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000093', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000007', 'Read this when I was deciding whether to install superpowers. Decided no — too much methodology for solo work. But the conversation-memory pattern at the end is something I want to build for my own setup. Bookmarked for later.', '{"claude-code","wip-evaluating"}', '2026-03-22T10:15:00Z', '2026-03-22T10:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000094', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000009', 'Used this last week to generate a 14-page client proposal in 30 minutes. 🚢 Would have been a full day of formatting otherwise. The image-handling part is what saved me.', '{"document-generation","ship-this-week","cut-cost"}', '2026-03-26T13:33:00Z', '2026-03-26T13:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000095', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000055', 'Switched my second product to usage-based billing after this. MRR up 22% in the first month because users who''d churned on flat pricing came back. 🚢 The metering setup is more annoying than the docs suggest — budget half a day.', '{"stripe","monetisation","ship-this-week"}', '2026-03-30T16:08:00Z', '2026-03-30T16:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000096', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000020', 'Generated a 22-slide investor deck from a one-page brief in 90 minutes using this skill. 🚢 The image-and-chart-handling is the part that earned its keep — most pptx tools choke on that.', '{"document-generation","ship-this-week"}', '2026-04-04T11:22:00Z', '2026-04-04T11:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000097', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000023', 'Read this when deciding whether to install their skills. Convinced me. Installed both skills the same day. 🚢 The "agents know but use wrong" framing is exactly the gap I''d been hitting.', '{"supabase","field-notes"}', '2026-04-08T09:48:00Z', '2026-04-08T09:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000098', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000056', 'Worth scanning for the framework even if you disagree with the 3 specific picks. The "install per-project, not globally" argument is the right one — keeps the trigger surface small.', '{"claude-code","dev-velocity","field-notes"}', '2026-04-12T15:32:00Z', '2026-04-12T15:32:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000099', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000018', 'The Fast Research skill at the end is the one I actually installed. Saved me ~2 hours of manual web research per week. 🚢 The four-element prompt structure for skill-creator is the part I''m using when I write my own skills now.', '{"claude-code","ship-this-week","dev-velocity"}', '2026-04-16T10:08:00Z', '2026-04-16T10:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000057', 'Replaced my SendGrid setup with this in an afternoon. 🚢 Cleaner API, cheaper at my volume, the React Email integration is the thing that sold me. cut-cost on the email vendor switch.', '{"email","ship-this-week","cut-cost"}', '2026-04-20T13:45:00Z', '2026-04-20T13:45:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000101', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000013', 'The most navigable of the awesome-lists I''ve found. Categorised by official vs community vs domain, with timeline of how the skills ecosystem developed. Useful as a research starting point even if the individual entries vary wildly in quality.', '{"awesome-list","landscape","synthesis"}', '2025-11-18T10:15:00Z', '2025-11-18T10:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000102', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000058', 'Companion to the travisvn list. Different curation logic — leans heavier into community-submitted skills with descriptions of what each does. Worth holding both in view; neither is complete on its own.', '{"awesome-list","landscape"}', '2025-11-22T14:42:00Z', '2025-11-22T14:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000103', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000011', 'The most rigorous public evaluation of the skills hype I''ve seen. Two weeks installing 200+ skills, benchmarking against vanilla output. The argument that skills are ''prompt injections'' deflates a lot of the marketing language without dismissing the underlying utility. Pair with the Simon Willison piece for both poles of the debate.', '{"evaluation","practice-vs-protocol","synthesis"}', '2025-11-28T11:08:00Z', '2025-11-28T11:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000104', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000007', 'The origin essay for the superpowers framework. Reads as a practitioner reasoning out loud about why TDD-for-agents matters more than TDD-for-humans. The remembering-conversations skill described at the end is a quietly important pattern: SQLite + vector index + Haiku summary as long-term memory.', '{"methodology","practitioner-essay","agent-workflow"}', '2025-12-04T16:33:00Z', '2025-12-04T16:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000105', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000002', 'The framing essay everyone in this conversation cites. The argument that skills work because they outsource the hard parts to the LLM harness is the most useful mental model I''ve encountered for thinking about why some agent abstractions feel right and others feel forced.', '{"mental-model","synthesis","protocol-design"}', '2025-12-09T09:55:00Z', '2025-12-09T09:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000106', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000037', 'The reference essay for any conversation about agent design. The augmented-LLM-vs-agent distinction at the top is the load-bearing taxonomy. Pair with Simon Willison''s piece for the synthesis between the protocol-level and the practical-level views.', '{"agent-architecture","research-paper","synthesis"}', '2025-12-14T13:18:00Z', '2025-12-14T13:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000107', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000039', 'A field report rather than a framework. The honest accounting of token cost (15x a single-agent baseline) is the part that earned the post — most multi-agent essays elide this. Pair with the Effective Agents piece for the principled-vs-pragmatic balance.', '{"multi-agent","research-paper","field-notes"}', '2025-12-19T10:42:00Z', '2025-12-19T10:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000108', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000006', 'The canonical reference. The skills themselves are useful as exemplars, but the meta-pattern (vendor-shipping curated production skills) is the thing worth studying. This is the pattern HashiCorp and Supabase later copied.', '{"agent-skills","reference","landscape"}', '2025-12-23T14:25:00Z', '2025-12-23T14:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000109', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000044', 'The introduction of contextual chunking. The benchmarking methodology is the part worth studying as a research synthesis exercise — they isolate the specific failure mode (retrieval missing context) and report deltas, not just headline numbers. Practical and well-argued.', '{"rag","research-paper","synthesis"}', '2025-12-29T11:08:00Z', '2025-12-29T11:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000110', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000019', 'The most useful methodological piece on skill evaluation I''ve found. The point about "don''t make tasks too adversarial — you''ll test the agent, not the skill" is the kind of subtle framing that only emerges from real evaluation work. Pair with the corpwaters Ultimate Guide piece for the practitioner-side critique.', '{"evaluation","methodology","synthesis"}', '2026-01-05T15:32:00Z', '2026-01-05T15:32:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000111', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000008', 'The capability-uplift vs encoded-preference distinction is the most useful taxonomy I''ve seen for thinking about skill durability. Capability-uplift skills age out as models improve; encoded-preference skills don''t. Worth using as a categorisation when reviewing a team''s skill investments.', '{"mental-model","skill-authoring","synthesis"}', '2026-01-10T10:15:00Z', '2026-01-10T10:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000112', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000018', 'A practitioner-to-practitioner walkthrough with a live build session embedded. Useful as a counterweight to the more abstract framing pieces — sometimes you need the "here''s exactly what to type" version. Pair with the official skill-creator docs for theory-vs-practice.', '{"practitioner-essay","skill-authoring"}', '2026-01-15T13:48:00Z', '2026-01-15T13:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000113', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000003', 'The repo behind Jesse Vincent''s essay. The interesting structural choice is the SessionStart hook that forces skill discovery — most skill collections rely on the agent finding skills through descriptions; this one makes discovery a first-class step. Worth reading the architecture before installing.', '{"methodology","agent-architecture","practitioner-essay"}', '2026-01-20T11:22:00Z', '2026-01-20T11:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000114', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000059', 'Outside the skills conversation but adjacent. The sparse-autoencoder work on interpretability is what underlies the recent practical advice on "why some prompts work and others don''t." The architectural understanding helps you reason about prompt design more rigorously.', '{"interpretability","research-paper","mental-model"}', '2026-01-25T16:08:00Z', '2026-01-25T16:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000115', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000042', 'Interpretability research applied to operational concerns. The bit on attention heads selecting between competing instructions is a useful mental model for skill description writing — it explains why "pushy" descriptions outperform polite ones. Pair with the skill-creator getting-started doc.', '{"interpretability","research-paper","mental-model"}', '2026-01-30T10:55:00Z', '2026-01-30T10:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000116', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000026', 'Vercel''s vendor-shipped skills. Companion to anthropics/skills and supabase/agent-skills as exemplars of the vendor-shipped skill pattern. Worth holding all three in view for landscape comparison.', '{"agent-skills","vendor-skills","landscape"}', '2026-02-04T14:18:00Z', '2026-02-04T14:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000117', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000017', 'HashiCorp''s vendor-shipped skills, focused on Terraform and Packer. Completes the vendor-skills set: Anthropic (foundational), Vercel (frontend), Supabase (data), HashiCorp (infrastructure). The pattern is now established across at least four major vendors — worth treating as a settled landscape.', '{"agent-skills","vendor-skills","landscape"}', '2026-02-09T11:42:00Z', '2026-02-09T11:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000118', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000023', 'The vendor-perspective announcement post. The framing of the gap between "agent knows the tool" and "agent uses the tool correctly" is what motivates the vendor-shipped-skills movement. Worth reading alongside the HashiCorp introduction post for the pattern-recognition.', '{"vendor-skills","synthesis","field-notes"}', '2026-02-14T15:25:00Z', '2026-02-14T15:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000119', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000060', 'Companion announcement to Supabase''s. Different framing, same underlying motivation: vendor-shipped skills as a structural answer to LLM hallucination on tool-specific code. Useful as a synthesis read with the Supabase post.', '{"vendor-skills","synthesis","infrastructure"}', '2026-02-19T10:08:00Z', '2026-02-19T10:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000120', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000061', 'The self-improving-skills argument. Lifts Karpathy''s autoresearch concept into the skill-craft conversation: objective metric + measurement function + editable file = automated improvement loop. Whether this scales is genuinely open, but the thinking is fresh.', '{"practitioner-essay","synthesis","wip-patterns"}', '2026-02-24T13:42:00Z', '2026-02-24T13:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000121', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000016', 'The product launch piece, but worth reading as a research-thesis statement. The bet is that design tooling becomes a generation-and-iteration surface rather than a manipulation-of-pixels surface. Whether this changes the design profession or just the design-tool market is the open question.', '{"design-tools","synthesis","field-notes"}', '2026-03-01T10:15:00Z', '2026-03-01T10:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000122', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000024', 'The practitioner companion to the Claude Design announcement. The meta-skill pattern (a skill that builds your brand skill from your website) is the actually-novel idea — pair with the official Claude Design docs for the principle-and-implementation view.', '{"design-tools","practitioner-essay","synthesis"}', '2026-03-06T15:32:00Z', '2026-03-06T15:32:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000123', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000046', 'Worth reading as much for the model-tier strategy as for Haiku itself. The orchestrator-Sonnet, worker-Haiku pattern is now the assumed architecture for multi-agent work. Pair with the Multi-agent Research System post for the implementation view.', '{"models","synthesis","multi-agent"}', '2026-03-11T11:25:00Z', '2026-03-11T11:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000124', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000062', 'Foundational paper. The two-phase training approach (SL + RL with AI feedback) is the architectural ancestor of a lot of the later instruction-following work. Worth re-reading periodically — the framing has held up.', '{"research-paper","alignment","synthesis"}', '2026-03-16T14:08:00Z', '2026-03-16T14:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000125', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000001', 'The meta-skill that scaffolds new skills. Worth reading as a primary text on what "good skill design" means according to Anthropic. The frontmatter conventions and the trigger-language guidance are the parts most community skills get wrong.', '{"skill-authoring","reference","synthesis"}', '2026-03-21T09:55:00Z', '2026-03-21T09:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000126', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000002', 'The clarity of the writing is doing as much work as the argument. ✦ Lesson for me — write about new things in plain sentences, not in the in-group dialect.', '{"field-notes","agent-thinking"}', '2026-01-08T11:42:00Z', '2026-01-08T11:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000127', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000022', 'The three-stage workflow (Context → Refinement → Reader Testing) is honestly how I want to work on brand decks too. The "test the doc with a fresh Claude with no context" move is a very good idea I''m stealing for ALL my deliverables. ✦', '{"writing-process","craft"}', '2026-01-13T15:18:00Z', '2026-01-13T15:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000128', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000005', 'Reading this as someone who barely uses Claude Code. The CLAUDE.md-as-styleguide framing is the bit that made it click — it''s not a prompt, it''s a brand brief for how the agent should behave.', '{"claude-code","getting-started"}', '2026-01-18T10:25:00Z', '2026-01-18T10:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000129', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000001', 'The structure here is intimidating but the analogy that finally helped — a skill is a one-page brand guide for a specific behaviour. Frontmatter is the metadata, body is the rules, examples are the dos-and-don''ts. ✦', '{"skill-authoring","getting-started"}', '2026-01-22T14:08:00Z', '2026-01-22T14:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000130', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000007', 'The discipline here is the thing. Reading an engineer write about working with agents the way I''d want a senior creative director to write about working with juniors. ✦', '{"practitioner-essay","craft"}', '2026-01-27T11:55:00Z', '2026-01-27T11:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000131', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000016', 'The bet that design tooling becomes generation-and-iteration is the right one. Not sure yet if it''s the right tool *for me* — the question is whether the design system holds fidelity through iteration, which is the part you can''t see in a demo. ✦', '{"design-tools","field-notes"}', '2026-02-01T16:42:00Z', '2026-02-01T16:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000132', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000024', 'The meta-skill idea (a skill that builds your brand skill) is the part I''m chewing on. ✦ Lesson for me — your brand isn''t your style guide PDF, it''s the system that *generates* the style guide.', '{"design-tools","craft","brand"}', '2026-02-06T13:33:00Z', '2026-02-06T13:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000133', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000063', 'Old-school typography reference but still the cleanest explanation of typeface anatomy I''ve found. ✦ The section on x-height-to-cap-height ratio explains why some pairings feel right at small sizes and others don''t.', '{"type","reference","craft"}', '2026-02-11T09:48:00Z', '2026-02-11T09:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000134', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000064', 'The argument that design tools are themselves designed objects is one I keep coming back to. ✦ Lesson for me — when I''m choosing a tool, I''m also choosing a worldview about what design *is*.', '{"design-tools","craft","field-notes"}', '2026-02-16T15:08:00Z', '2026-02-16T15:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000135', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000009', 'Reading this for the *prose*, not the function. ✦ The way the trigger conditions are written — concrete, specific, slightly bossy — is exactly the voice I want in my own brief-writing.', '{"writing-process","craft"}', '2026-02-20T11:22:00Z', '2026-02-20T11:22:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000136', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000037', 'Out of my technical depth on the implementation but the language of "orchestrator" and "worker" agents reads like a creative-team org chart. ✦ The mental model transfers — replace agent with junior designer and the patterns are the same.', '{"agent-thinking","field-notes"}', '2026-02-25T14:42:00Z', '2026-02-25T14:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000137', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000065', 'Figma''s answer to Claude Design. Saving for the comparison — the philosophical difference (design-system-aware vs prompt-driven) is the bit worth thinking about, not the feature lists.', '{"design-tools","field-notes"}', '2026-03-02T10:15:00Z', '2026-03-02T10:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000138', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000066', 'The deep-dive on Klim''s neutral grotesque pair. ✦ Reading typeface release notes is a habit I want to keep — they''re some of the most rigorous design writing in the world.', '{"type","craft","field-notes"}', '2026-03-07T13:28:00Z', '2026-03-07T13:28:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000139', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000006', 'Saving the root for navigation. ✦ The taxonomy of these skills (document, agent, code) is itself instructive — it''s a visual map of what Anthropic thinks the use-case landscape looks like.', '{"agent-skills","reference","getting-started"}', '2026-03-12T16:08:00Z', '2026-03-12T16:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000140', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000067', 'Mainstream design-press coverage of Claude Design. Useful as a tone reference — how the tool is being framed for non-technical designers shapes how it lands in the field. ✦ Lesson for me — the framing matters as much as the feature.', '{"design-tools","field-notes"}', '2026-03-17T10:42:00Z', '2026-03-17T10:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000141', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000068', 'The visual breakdown of prompt structure — the way it''s diagrammed makes the implicit components legible. ✦ The structure here is doing as much work as the content. Stealing the diagram pattern for my own teaching.', '{"prompting","craft","getting-started"}', '2026-03-22T15:25:00Z', '2026-03-22T15:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000142', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000069', 'The argument that AI interfaces have settled on a quiet, restrained type voice — and the question of whether that''s the right call. ✦ The piece is itself well-typeset, which is the metalevel reason I''m saving it.', '{"type","design-tools","craft"}', '2026-03-27T11:08:00Z', '2026-03-27T11:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000143', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000003', 'Reading the writing-skills skill specifically as a brief-writing reference. ✦ The TDD-for-documentation framing translates directly to design briefing — write the test for whether the brief landed *before* you write the brief.', '{"craft","writing-process"}', '2026-04-01T13:42:00Z', '2026-04-01T13:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000144', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000070', 'Studio essay on how tool affordances shape design output. ✦ Lesson for me — the choice between Claude Design, Figma, and Webflow isn''t a feature comparison, it''s a decision about what *kind* of designer the tool wants you to be.', '{"design-tools","craft","field-notes"}', '2026-04-06T09:55:00Z', '2026-04-06T09:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000145', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000011', 'Read this for the contrarian discipline — most of the AI-tool writing I see is enthusiast-mode. The methodological rigour here is what good design criticism looks like applied to a different field. ✦', '{"evaluation","field-notes","craft"}', '2026-04-11T14:18:00Z', '2026-04-11T14:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000146', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000007', 'Re-reading after using superpowers for two months. ✦ The bit about brainstorming before plan-then-execute is the move I keep using — it maps directly to the explore-then-narrow phase of any creative process.', '{"practitioner-essay","craft","design-process"}', '2026-04-16T10:32:00Z', '2026-04-16T10:32:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000147', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000071', 'Design-press coverage of the Claude Design launch. ✦ Lesson for me — the way the design community received the launch (cautiously, with scepticism about brand fidelity) is itself a useful signal about where the actual user concern sits.', '{"design-tools","field-notes"}', '2026-04-21T15:08:00Z', '2026-04-21T15:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000148', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000072', 'Old essay but the framework is durable. ✦ The taxonomy of typographic voice (authoritative, approachable, technical, lyrical) is the language I''ve been missing when reviewing brand work.', '{"type","craft","brand"}', '2026-04-25T11:42:00Z', '2026-04-25T11:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000149', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000073', 'A skill that takes a brand reference and outputs a design system page + A4 brand book PDF. ✦ Saving for the workflow — the idea of "brand brief in, generated artifact out" is one I want to test on my own client work.', '{"design-tools","craft","brand"}', '2026-04-27T13:25:00Z', '2026-04-27T13:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000150', '00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000074', 'The reference I keep returning to. ✦ The opinionated framing ("if you want to be taken seriously, follow these rules") is exactly the right voice for a typography manual — confident without being prescriptive.', '{"type","reference","craft"}', '2026-04-28T09:15:00Z', '2026-04-28T09:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000151', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000004', 'Adopted as our team''s default React perf reference. We forked the repo and added 8 internal rules at the top of each category. Two things made this work as a team-shared skill: the prefix codes (so we can link to specific rules in code review) and the impact-prioritisation (so the team agrees on what matters most). Worth saving even if you''re not on Next.', '{"react","for-the-team","internal-standards"}', '2025-11-25T09:42:00Z', '2025-11-25T09:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000152', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000006', 'The canonical reference. We use the docx, pdf, and pptx skills wholesale (no fork) because production-quality document generation is not a thing we want to maintain. Worth noting these three are source-available not open source, which mattered for our compliance review.', '{"agent-skills","reference","for-the-team"}', '2025-11-29T14:18:00Z', '2025-11-29T14:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000153', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000003', 'Evaluated this for team-wide adoption. Conclusion: too prescriptive for our team''s range of work — TDD-by-default doesn''t fit the experimental work some of our engineers do. We pulled the brainstorming and writing-plans skills as standalones and skipped the rest. The marketplace pattern itself (hookable session-start, forced skill discovery) is worth borrowing for our internal skill library.', '{"claude-code","methodology","team-evaluated"}', '2025-12-04T10:55:00Z', '2025-12-04T10:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000154', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000011', 'Sent to the team as required reading before our internal-skills sprint. The "20% trigger rate" data point reframed our acceptance criteria — we now require benchmarked-against-baseline data before adding a skill to the org-wide library. Saved us shipping at least four skills that would have made things worse.', '{"evaluation","for-the-team","internal-standards"}', '2025-12-09T16:32:00Z', '2025-12-09T16:32:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000155', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000005', 'Used as the basis for our internal Claude Code onboarding doc. The "treat CLAUDE.md like code" framing — review when things go wrong, prune regularly, test changes by observing behaviour — landed well with engineers used to thinking that way. The keep-it-under-200-lines guidance has held up for us at team scale.', '{"claude-code","claude-md","onboarding"}', '2025-12-14T11:08:00Z', '2025-12-14T11:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000156', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000017', 'Adopted across our infrastructure team within a week of the announcement. Two things drove the decision: vendor-shipped means HashiCorp owns version compatibility (we don''t have to update the skills when Terraform releases ship), and the style-guide skill enforces our existing Terraform standards without us writing the rules ourselves. for-the-team win.', '{"terraform","for-the-team","vendor-skills"}', '2025-12-19T15:42:00Z', '2025-12-19T15:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000157', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000012', 'Evaluated alongside the HashiCorp skills. Same vendor-shipped pattern, same team-friendly characteristics. Adopted both. The pattern itself (vendor ships skills with their tools) is what we now recommend the team look for first — community skills only when no vendor option exists.', '{"supabase","for-the-team","vendor-skills"}', '2025-12-23T10:25:00Z', '2025-12-23T10:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000158', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000037', 'Required reading for any engineer on the team building agent-backed features. The augmented-LLM vs agent distinction at the top is the framework we use in design reviews — it forces a conscious choice rather than defaulting to whichever pattern someone reached for first. internal-standards.', '{"agent-architecture","internal-standards","for-the-team"}', '2025-12-28T13:18:00Z', '2025-12-28T13:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000159', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000019', 'The methodology informed our internal eval framework for team-built skills. Key takeaway adopted: the test environment must be reproducible (we use a Docker scaffold, as they recommend) or your eval results don''t transfer between engineers. Sent to the team as the canonical reference for skill evaluation.', '{"evaluation","internal-standards","for-the-team"}', '2026-01-03T11:55:00Z', '2026-01-03T11:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000160', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000008', 'We migrated our internal skill-eval workflow to use the new skill-creator benchmark mode the week this shipped. The capability-uplift vs encoded-preference distinction is now in our skill review template — engineers must classify their skill before submission. Reduced shipped-skill churn meaningfully.', '{"skill-authoring","internal-standards","team-process"}', '2026-01-08T14:42:00Z', '2026-01-08T14:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000161', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000001', 'Required pre-read for any engineer writing their first internal skill. We also added an internal companion doc that maps skill-creator''s recommendations to our team conventions (file locations, naming, review process). The skill-creator itself stays unmodified — we don''t fork what Anthropic ships.', '{"skill-authoring","onboarding","internal-standards"}', '2026-01-13T10:08:00Z', '2026-01-13T10:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000162', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000026', 'We adopted react-best-practices and react-composition wholesale. web-best-practices was too generic for our use case so we forked and trimmed. The bigger lesson for the team: vendor-shipped skills are negotiable surfaces — we can fork and customise where it makes sense without losing the upstream upgrade path.', '{"react","for-the-team","vendor-skills"}', '2026-01-18T15:25:00Z', '2026-01-18T15:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000163', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000039', 'Required reading before our team started any multi-agent feature work. The honest accounting of token cost (15x baseline) is what changed our estimation process — we now budget multi-agent features at 10-20x single-agent baseline by default, and require justification when going beyond.', '{"multi-agent","internal-standards","for-the-team"}', '2026-01-23T11:42:00Z', '2026-01-23T11:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000164', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000023', 'Sent to the team to explain why we adopted the Supabase agent-skills. The framing of "agent knows the tool" vs "agent uses the tool correctly" is the gap our engineers had been hitting and couldn''t articulate. team-evaluated.', '{"supabase","for-the-team","team-evaluated"}', '2026-01-28T09:55:00Z', '2026-01-28T09:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000165', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000060', 'Companion to the Supabase post. We use both posts together when explaining the vendor-shipped-skills pattern to engineers new to the team. The shared insight (vendor knows their tool best, ships skills with the product) is the meta-pattern we want engineers to internalise.', '{"terraform","for-the-team","vendor-skills"}', '2026-02-02T13:18:00Z', '2026-02-02T13:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000166', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000007', 'Required reading for engineers evaluating whether to install the superpowers framework. We didn''t adopt it team-wide (too prescriptive for our range of work) but the underlying TDD-for-agents argument informed how we structured our internal skill-quality criteria. Worth reading even if you don''t install.', '{"practitioner-essay","team-evaluated","methodology"}', '2026-02-07T16:42:00Z', '2026-02-07T16:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000167', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000040', 'Evaluated against the HashiCorp official terraform skills. Decision: stay with the HashiCorp version for the official-vendor benefit, but read antonbabenko''s testing-strategy decision matrix as supplementary reference. Forking community skills for team use without vendor backing is a maintenance burden we want to avoid.', '{"terraform","team-evaluated"}', '2026-02-12T10:25:00Z', '2026-02-12T10:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000168', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000009', 'We use this skill wholesale for client deliverable generation. Two things justify the no-fork decision: production-quality document generation is not our differentiator, and the source-available licensing means our compliance team approved use without a custom audit.', '{"document-generation","for-the-team","production-skills"}', '2026-02-17T14:08:00Z', '2026-02-17T14:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000169', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000018', 'Used the four-element prompt structure from this piece as the basis for our internal skill-template. Engineers writing their first skill now follow a standardised opening — reduced skill review time by about 30% because the structural questions are pre-answered.', '{"skill-authoring","internal-standards","onboarding"}', '2026-02-22T11:33:00Z', '2026-02-22T11:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000170', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000044', 'Adopted the contextual-chunking pattern in our internal RAG infrastructure within two weeks of this post. ~30% reduction in retrieval-quality issues across our docs-search systems, in line with their reported numbers. The Haiku-call-per-chunk cost is real but justified at our scale.', '{"rag","for-the-team","infrastructure"}', '2026-02-27T15:48:00Z', '2026-02-27T15:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000171', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000036', 'Required reading for any engineer building Claude-API-backed features. The decision tree at the top settles the "which surface do I use" question before engineers waste time prototyping the wrong thing. Adopted as part of the onboarding flow.', '{"claude-api","onboarding","internal-standards"}', '2026-03-04T10:18:00Z', '2026-03-04T10:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000172', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000027', 'Adopted as our team''s reference for any Postgres performance work. We forked once (to add 6 internal rules around our specific RLS patterns) and have stayed in sync with upstream since. The CRITICAL/HIGH/MEDIUM impact tiering is the part that made this work for code review — engineers can prioritise without re-reading the whole skill.', '{"postgres","for-the-team","internal-standards"}', '2026-03-09T13:42:00Z', '2026-03-09T13:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000173', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000013', 'We use this as the team''s discovery surface for new skills. Engineers propose additions to the internal library by linking to entries here first. Has saved us evaluating ~12 skills that turned out to be redundant with what we already had.', '{"awesome-list","team-process","for-the-team"}', '2026-03-14T11:08:00Z', '2026-03-14T11:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000174', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000046', 'Triggered an internal review of our model-tier strategy. Adopted Haiku 4.5 as the default for sub-agent work in our orchestrator-worker patterns. Cost reduction of about 60% on our internal multi-agent eval workloads, with no measurable quality regression. for-the-team.', '{"models","for-the-team","infrastructure"}', '2026-03-19T15:25:00Z', '2026-03-19T15:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000175', '00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000043', 'One of the two superpowers skills we adopted as a standalone (the other being brainstorming). The forced explicit-success-criteria step matches our internal RFC discipline — engineers were already writing this informally; the skill made it consistent. Recommended for teams with similar planning culture.', '{"claude-code","team-process","for-the-team"}', '2026-03-24T09:42:00Z', '2026-03-24T09:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000176', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000075', 'The first thing that made Claude Code feel approachable. 🌱 The "I Googled what is a terminal" bit — same.', '{"getting-started","helped-me-understand","non-technical"}', '2026-02-12T10:48:00Z', '2026-02-12T10:48:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000177', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000076', 'The skill-developer-as-recipe analogy actually clicked for me. I always thought you had to "code" a skill but it''s really just writing instructions in a markdown file? 🌱', '{"getting-started","non-technical","bookmark-for-later"}', '2026-02-15T14:18:00Z', '2026-02-15T14:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000178', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000001', 'Saving this because everyone references it. Most of it is over my head right now but the YAML frontmatter and the "make descriptions pushy" bit make sense. 🌱', '{"skill-authoring","still-figuring-out"}', '2026-02-19T11:25:00Z', '2026-02-19T11:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000179', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000002', 'Don''t fully understand MCP yet so half of the comparison was lost on me, but the "skills are just markdown files with a bit of YAML" line was the moment I stopped being scared of them.', '{"agent-thinking","helped-me-understand"}', '2026-02-23T15:42:00Z', '2026-02-23T15:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000180', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000006', 'The big one. Going to read /docx and /pdf as my "what does a real skill actually look like" examples. 🌱', '{"reference","bookmark-for-later"}', '2026-02-27T09:08:00Z', '2026-02-27T09:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000181', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000077', 'I think this is the most useful guide I''ve found for someone like me. 🌱 The four steps (build, evaluate, save, install) made the whole flow make sense. Following this for my next attempt.', '{"getting-started","non-technical","helped-me-understand"}', '2026-03-03T13:33:00Z', '2026-03-03T13:33:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000182', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000005', 'Reading this because everyone says CLAUDE.md is important. I think I get the basic idea? It''s like... an instruction file you put in your project folder? 🌱 still-figuring-out the difference between this and a skill.', '{"claude-code","still-figuring-out","getting-started"}', '2026-03-07T10:55:00Z', '2026-03-07T10:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000183', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000011', 'Read because @sasha-chen recommended it. The bit about most skills making things worse was scary — I was about to install ~10 skills from awesome-list. Going to be more careful now. 🌱 helped-me-understand that more skills isn''t always better.', '{"evaluation","helped-me-understand","still-figuring-out"}', '2026-03-11T16:18:00Z', '2026-03-11T16:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000184', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000009', 'Looking at this as the "what does a real one look like" example. 🌱 The structure is clearer than I expected — there''s a description at the top and then just... instructions in markdown? I think I could write one of these now?', '{"bookmark-for-later","helped-me-understand"}', '2026-03-15T11:42:00Z', '2026-03-15T11:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000185', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000016', 'I tried Claude Design last week. It made me a landing page mockup in about 20 minutes that looked better than what I would have made in Figma in a day. 🌱 Still figuring out if I should feel weird about that.', '{"design-tools","still-figuring-out","helped-me-understand"}', '2026-03-19T14:08:00Z', '2026-03-19T14:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000186', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000018', 'The Fast Research skill they include at the end was the first skill I successfully installed and used. 🌱 helped-me-understand that you don''t have to write skills yourself — you can install ones other people made. Which seems obvious in hindsight.', '{"getting-started","helped-me-understand"}', '2026-03-23T10:25:00Z', '2026-03-23T10:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000187', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000007', 'Saved because @jules-vidal kept mentioning it. Most of the engineering parts went over my head but the bit about working with the agent like a junior employee instead of a search engine made sense. 🌱', '{"bookmark-for-later","helped-me-understand"}', '2026-03-27T13:18:00Z', '2026-03-27T13:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000188', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000024', 'I don''t have a website yet, but the idea that you could make a skill that makes other skills was a wild moment for me. 🌱 still-figuring-out what "meta-skill" really means but the example here makes it concrete.', '{"design-tools","still-figuring-out","helped-me-understand"}', '2026-04-01T15:42:00Z', '2026-04-01T15:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000189', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000013', 'My main browsing surface for finding skills now. 🌱 Going through the design-related ones one at a time instead of installing everything (lesson from the corpwaters article).', '{"awesome-list","bookmark-for-later"}', '2026-04-05T11:08:00Z', '2026-04-05T11:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000190', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000068', 'The diagram at the top of this finally made the difference between role, context, task, and constraints click for me. 🌱 helped-me-understand why my prompts were getting weird answers — I was missing context most of the time.', '{"prompting","helped-me-understand","getting-started"}', '2026-04-09T14:25:00Z', '2026-04-09T14:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000191', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000074', 'Not AI-related but @anika-laine recommended it for design fundamentals. 🌱 The "if you only read one thing" page is probably the most useful single page of design writing I''ve found.', '{"type","getting-started","bookmark-for-later"}', '2026-04-13T10:42:00Z', '2026-04-13T10:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000192', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000008', 'Read this because skill-creator is the only skill-related thing I really use. 🌱 The capability-uplift vs encoded-preference distinction took me a while but I think I get it now — capability ones might stop being needed, preference ones won''t. Bookmarked because I''ll forget.', '{"skill-authoring","still-figuring-out","bookmark-for-later"}', '2026-04-17T15:18:00Z', '2026-04-17T15:18:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000193', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000077', 'Re-read this after my third successful skill install. 🌱 Different things stand out now — the bit about evaluation being the step most people skip is the one I''d skipped on the first read. Going to add evaluation to my next skill build.', '{"getting-started","helped-me-understand"}', '2026-04-21T11:55:00Z', '2026-04-21T11:55:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000194', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000065', 'Saving because I''ve used Figma since I started learning design and now they have an AI tool too. 🌱 still-figuring-out if I should be using Claude Design or Figma Make — they seem to do similar things but maybe for different people?', '{"design-tools","still-figuring-out"}', '2026-04-24T13:42:00Z', '2026-04-24T13:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000195', '00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000014', 'The docs inside the skill-creator skill itself. 🌱 Recursive in a way that took me a minute to understand — there''s a skill that helps you write skills, and inside it is a guide that explains how to write skills. helped-me-understand that the official docs are inside the tool itself.', '{"skill-authoring","getting-started","helped-me-understand"}', '2026-04-26T09:25:00Z', '2026-04-26T09:25:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000196', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000039', 'the orchestrator-workers pattern keeps coming up. been thinking about whether the same shape applies to design exploration — one director-agent generating brief, multiple variant-agents producing options. probably yes for visual exploration, probably no for IA work where coherence matters.', '{"multi-agent","design-process","field-notes"}', '2026-04-29T08:30:00Z', '2026-04-29T08:30:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000197', '00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000001', 'Re-reading after writing five skills. The frontmatter discipline matters more than I gave it credit for the first time through. The "description should make Claude *want* to use it" guideline is doing more work than my initial pass appreciated.', '{"skill-authoring","field-notes"}', '2026-04-29T11:15:00Z', '2026-04-29T11:15:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000198', '00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000007', 'Late to this one. The TDD-for-agents framing transfers cleanly to design-system component authoring — write the test (visual diff) before the component, watch it fail, build it, watch it pass. Borrowing the discipline.', '{"practitioner-essay","design-engineering","tdd-for-skills"}', '2026-04-29T14:42:00Z', '2026-04-29T14:42:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000199', '00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000016', 'Re-saving after a month of using it. 🚢 The brand-from-codebase claim has held up — onboarded my third product to it last week. cut the design phase from 4 days to 1 day. The fidelity loss vs hand-built is real but worth it for the speed.', '{"design-tools","ship-this-week","cut-cost"}', '2026-04-29T16:08:00Z', '2026-04-29T16:08:00Z');
INSERT INTO public.saves (id, user_id, url_id, notes, tags, created_at, updated_at) VALUES ('20000000-0000-0000-0000-000000000200', '00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000044', 'Re-reading six months later. The contextual-chunking pattern has become standard practice across the RAG ecosystem in that time — the speed of adoption is the meta-observation worth recording. When good ideas have low implementation cost, they propagate fast. Pair with the LangChain Evaluating Skills piece for the methodology that makes this measurable.', '{"rag","synthesis","field-notes"}', '2026-04-29T17:33:00Z', '2026-04-29T17:33:00Z');
